db.orders.aggregate([
  { $match: {
      status: "completed",
      createdAt: { $gte: ISODate("2024-01-01"), $lt: ISODate("2025-01-01") }
  } },
  { $group: {
      _id: "$customerId",
      totalRevenue: { $sum: "$amount" },
      orderCount: { $sum: 1 }
  } },
  { $sort: { totalRevenue: -1 } },
  { $limit: 5 },
  { $project: { _id: 0, customerId: "$_id", totalRevenue: 1, orderCount: 1 } }
]);

db.orders.aggregate([
  { $lookup: {
      from: "users",
      localField: "userId",
      foreignField: "_id",   // _id is indexed -> efficient join
      as: "user"
  } },
  { $unwind: "$user" },        // [ {..} ] -> {..}
  { $project: {
      _id: 0,
      orderId: "$_id",
      email: "$user.email",
      amount: 1
  } }
]);

db.employees.aggregate([
  { $group: {
      _id: "$salary",
      employees: { $push: "$name" }
  } },
  { $sort: { _id: -1 } },
  { $skip: 1 },   // drop the highest distinct salary
  { $limit: 1 },  // take the second-highest
  { $project: { _id: 0, salary: "$_id", employees: 1 } }
]);

